long long memo[50];            // 0 means not computed yet

long long ways(int n) {
    if (n <= 1) return 1;                  // base cases
    if (memo[n]) return memo[n];           // already solved: reuse
    return memo[n] = ways(n - 1) + ways(n - 2);
}

int n = 5;
vector<long long> dp(n + 1);
dp[0] = dp[1] = 1;
for (int i = 2; i <= n; i++)
    dp[i] = dp[i - 1] + dp[i - 2];
cout << dp[n];
